import * as React from "react";

export function WarpText({ text = "WARP", className = "" }: { text?: string; className?: string }): React.JSX.Element {
  const [t, setT] = React.useState(0);
  React.useEffect(() => { const id = setInterval(() => setT(p => p + 0.05), 16); return () => clearInterval(id); }, []);
  return (
    <div className={`flex gap-0.5 font-display font-black text-5xl text-ink select-none ${className}`}>
      {text.split("").map((c, i) => (
        <span key={i} style={{ display: "inline-block", transform: `translateY(${Math.sin(t + i * 0.6) * 12}px) scaleX(${1 + Math.sin(t + i * 0.4) * 0.1})`, transition: "none" }}>
          {c === " " ? " " : c}
        </span>
      ))}
    </div>
  );
}

import * as React from "react";
import { WarpText } from "./warp-text";

export default function WarpTextDemo(): React.JSX.Element {
  return (
    <div className="flex min-h-[360px] w-full items-center justify-center rounded-2xl bg-neutral-950 p-8 border border-neutral-800">
      <WarpText
        text="Next Generation Web Interfaces"
        className="text-3xl sm:text-5xl font-mono font-bold tracking-tight text-white text-center"
      />
    </div>
  );
}
